import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * In-memory store of every message sent through the contact form. Shared by all
 * sessions, so the list survives leaving and coming back to the view.
 */
@Service
public class ContactMessages {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void add(ContactMessage message) {
        messages.add(0, message);
    }

    /** Newest first. */
    public List<ContactMessage> findAll() {
        return List.copyOf(messages);
    }
}
